package org.apache.commons.math3.genetics;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.exception.NumberIsTooSmallException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for ListPopulation#iterator.
 */
public class ListPopulation_iterator_TriageGen4Test {

    /**
     * Mock Chromosome implementation for testing purposes.
     */
    private static class MockChromosome implements Chromosome {
        @Override
        public double getFitness() {
            return 1.0;
        }

        @Override
        public Chromosome copy() {
            return new MockChromosome();
        }
    }

    @Test
    public void testIteratorWithEmptyPopulation() {
        int limit = 10;
        ListPopulation population = new ListPopulation(limit);

        Iterator<Chromosome> iterator = population.iterator();

        assertNotNull("Iterator should not be null", iterator);
        assertFalse("Iterator should be empty for a new population", iterator.hasNext());
    }

    @Test
    public void testIteratorWithPopulatedList() {
        int limit = 10;
        Chromosome c1 = new MockChromosome();
        Chromosome c2 = new MockChromosome();
        List<Chromosome> chromosomes = Arrays.asList(c1, c2);

        ListPopulation population = new ListPopulation(chromosomes, limit);

        Iterator<Chromosome> iterator = population.iterator();

        assertNotNull("Iterator should not be null", iterator);
        assertTrue("Iterator should have elements", iterator.hasNext());

        int count = 0;
        while (iterator.hasNext()) {
            Chromosome c = iterator.next();
            assertEquals("Chromosome should match the input", chromosomes.get(count), c);
            count++;
        }
        assertEquals("Iterator should have traversed all elements", 2, count);
        assertFalse("Iterator should be exhausted", iterator.hasNext());
    }

    @Test
    public void testIteratorAfterAddingChromosomes() {
        int limit = 10;
        ListPopulation population = new ListPopulation(limit);
        Chromosome c1 = new MockChromosome();

        population.addChromosome(c1);

        Iterator<Chromosome> iterator = population.iterator();

        assertTrue("Iterator should have element after addition", iterator.hasNext());
        assertEquals("Iterator should return the added chromosome", c1, iterator.next());
        assertFalse("Iterator should be exhausted", iterator.hasNext());
    }

    @Test
    public void testIteratorAfterSetChromosomes() {
        int limit = 10;
        ListPopulation population = new ListPopulation(limit);
        Chromosome c1 = new MockChromosome();
        Chromosome c2 = new MockChromosome();
        List<Chromosome> newList = Arrays.asList(c1, c2);

        population.setChromosomes(newList);

        Iterator<Chromosome> iterator = population.iterator();

        int count = 0;
        while (iterator.hasNext()) {
            Chromosome c = iterator.next();
            assertEquals(newList.get(count), c);
            count++;
        }
        assertEquals(2, count);
    }

    @Test
    public void testIteratorWithEmptyList() {
        int limit = 10;
        List<Chromosome> emptyList = Collections.emptyList();
        ListPopulation population = new ListPopulation(emptyList, limit);

        Iterator<Chromosome> iterator = population.iterator();

        assertNotNull(iterator);
        assertFalse(iterator.hasNext());
    }
}
